WITH valid_departments AS (SELECT *, LENGTH(location) location_length FROM departments WHERE NOT (budget BETWEEN 3424000 AND 3890000 OR budget <= 2654000)), departments_stats AS (SELECT CASE WHEN location_length >= 76 THEN 'high' WHEN location_length >= 19 THEN 'mid' ELSE 'low' END location_length_bucket, MAX(budget) max_budget FROM valid_departments GROUP BY CASE WHEN location_length >= 76 THEN 'high' WHEN location_length >= 19 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats WHERE max_budget >= 2074000 ORDER BY location_length_bucket;
